import bisect

def solve(nums):
    """Return length of longest strictly increasing subsequence in list nums.
    Uses patience sorting with binary search O(n log n).
    """
    if not nums:
        return 0
    # tails[i] = smallest possible tail value of an increasing subsequence of length i+1
    tails = []
    for x in nums:
        # find insertion point: first element >= x (since strict, we need >? Actually we want strictly increasing, so we replace first >= x)
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

