def solve(line):
    """Split one CSV line into fields.

    Fields may be wrapped in double quotes. Inside quotes, commas are
    literal and a doubled quote ("") means one quote character.
    A single trailing line terminator (\\n, \\r\\n or \\r) is ignored.
    """
    # A CSV line may carry a trailing newline; strip it like csv.reader does.
    for term in ('\r\n', '\n', '\r'):
        if line.endswith(term):
            line = line[:-len(term)]
            break

    fields = []
    cur = []
    in_quotes = False
    at_field_start = True  # nothing added to the current field yet
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and line[i + 1] == '"':
                    cur.append('"')
                    i += 2
                    continue
                in_quotes = False  # closing quote
            else:
                cur.append(ch)
        else:
            if ch == '"':
                if at_field_start:
                    in_quotes = True  # opening quote of a quoted field
                else:
                    cur.append(ch)  # quote in the middle of a bare field
            elif ch == ',':
                fields.append(''.join(cur))
                cur = []
                at_field_start = True
                i += 1
                continue
            else:
                cur.append(ch)
        at_field_start = False
        i += 1
    fields.append(''.join(cur))
    return fields

def solve(intervals):
    """Merge overlapping or touching [start, end] intervals; sort by start."""
    if not intervals:
        return []
    ivs = sorted(intervals, key=lambda iv: (iv[0], iv[1]))
    merged = [list(ivs[0])]
    for start, end in ivs[1:]:
        if start <= merged[-1][1]:  # overlaps or touches the last merged one
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

