def solve(s):
    s = str(s)
    n = len(s)
    if n <= 1:
        return s
    best_start, best_len = 0, 1
    for center in range(n):
        for l, r in ((center, center), (center, center + 1)):
            while l >= 0 and r < n and s[l] == s[r]:
                l -= 1
                r += 1
            l += 1
            length = r - l
            if length > best_len:  # strict > keeps earliest-start on ties
                best_start, best_len = l, length
