def solve(intervals):
    """Merge overlapping or touching intervals.
    Each interval may have start > end; we treat it as [min, max].
    Returns merged intervals sorted by start.
    """
    if not intervals:
        return []
    # Normalize intervals to [start, end] with start <= end
    norm = []
    for iv in intervals:
        if len(iv) < 2:
            continue
        s, e = iv[0], iv[1]
        if s > e:
            s, e = e, s
        norm.append([s, e])
    if not norm:
        return []
    norm.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = norm[0]
    for s, e in norm[1:]:
        if s <= cur_end:  # overlap or touch
            if e > cur_end:
                cur_end = e
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = s, e
    merged.append([cur_start, cur_end])
    return merged

